-- Modify "sessions" table
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_acr" CHECK ((acr)::text ~ '^[!-~]{1,255}$'::text), ADD CONSTRAINT "sessions_acrs" CHECK ((acrs)::text ~ '^$|^[!-~]{1,255}( [!-~]{1,255}){0,15}$'::text), ADD CONSTRAINT "sessions_amr" CHECK ((amr)::text ~ '^$|^[A-Za-z0-9_.:-]{1,64}( [A-Za-z0-9_.:-]{1,64}){0,15}$'::text), ADD CONSTRAINT "sessions_assurance" CHECK ((assurance)::text = ANY (ARRAY['none'::text, 'mfa'::text, 'phishing_resistant'::text])), ADD COLUMN "assurance" character varying NOT NULL DEFAULT 'none', ADD COLUMN "amr" character varying NOT NULL DEFAULT '', ADD COLUMN "acr" character varying NULL, ADD COLUMN "acrs" character varying NOT NULL DEFAULT '', ADD COLUMN "auth_time" timestamptz NULL;
-- Modify "tenants" table
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_mfa_policy" CHECK ((mfa_policy)::text = ANY (ARRAY['none'::text, 'mfa'::text, 'phishing_resistant'::text])), ADD COLUMN "mfa_policy" character varying NOT NULL DEFAULT 'none';
